"use client"

import { useState, useEffect, useRef } from 'react'
import Image from 'next/image'
import { Play, Clock, ThumbsUp } from "lucide-react"

export default function BookingPage() {
  const [slideIndex, setSlideIndex] = useState(0);
  const carouselRef = useRef(null);
  const slideWidthRef = useRef(0);
  const itemsPerView = 4; // Number of images per view

  useEffect(() => {
    const handleResize = () => {
      if (carouselRef.current && carouselRef.current.children[0]) {
        slideWidthRef.current = carouselRef.current.children[0].offsetWidth;
        carouselRef.current.style.transform = `translateX(-${slideIndex * slideWidthRef.current * itemsPerView}px)`;
      }
    };

    handleResize(); // Initial setup

    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, [slideIndex, itemsPerView]);

  const handleNext = () => {
    setSlideIndex((prevIndex) => (prevIndex + 1) % Math.ceil(images.length / itemsPerView));
  };

  const handlePrev = () => {
    setSlideIndex((prevIndex) => (prevIndex - 1 + Math.ceil(images.length / itemsPerView)) % Math.ceil(images.length / itemsPerView));
  };

  const images = [
    '/path/to/image1.jpg',
    '/path/to/image2.jpg',
    '/path/to/image3.jpg',
    '/path/to/image4.jpg',
    // Add more images as needed
  ];

  return (
    <section className="w-full py-20 relative">
      {/* Background image */}
      <div
        className="absolute inset-0 bg-cover bg-center bg-fixed z-0"
        style={{
          backgroundImage: "url('/placeholder.svg?height=1080&width=1920')",
        }}
      />

      {/* Content */}
      <div className="max-w-7xl mx-auto px-4 relative z-20">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          viewport={{ once: true, margin: "-100px" }}
          className="mb-12 text-center"
        >
          <h2 className="text-3xl md:text-4xl font-bold mb-4">Latest Comedy Clips</h2>
          <p className="text-muted-foreground max-w-2xl mx-auto">
            Check out some of my most popular stand-up moments and comedy sketches
          </p>
        </motion.div>

        {/* Carousel Controls */}
        <div className="absolute top-1/2 right-0 transform -translate-y-1/2 flex space-x-2">
          <button
            onClick={handlePrev}
            className="bg-black bg-opacity-50 text-white p-2 rounded-l-md"
          >
            Previous
          </button>
          <button
            onClick={handleNext}
            className="bg-black bg-opacity-50 text-white p-2 rounded-r-md"
          >
            Next
          </button>
        </div>

        {/* Carousel */}
        <div className="relative w-full overflow-hidden">
          <div
            ref={carouselRef}
            className="whitespace-nowrap transition-transform duration-500 ease-in-out"
            style={{ transform: `translateX(-${slideIndex * (slideWidthRef.current || 0) * itemsPerView}px)` }}
          >
            {images.map((image, index) => (
              <div key={index} className="inline-block w-1/4">
                <Image
                  src={image}
                  alt={`Carousel Image ${index + 1}`}
                  width={800}
                  height={500}
                  className="w-full rounded-xl p-2 h-auto object-cover"
                />
              </div>
            ))}
          </div>
        </div>

        {/* Contact Information */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.4 }}
          viewport={{ once: true, margin: "-100px" }}
          className="mt-12 text-center"
        >
          <h2 className="text-3xl font-bold text-gray-800 mb-8">Contact Information</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
              <h3 className="text-xl font-bold text-gray-700 mb-4">Phone Number</h3>
              <p className="text-gray-600">+123 456 7890</p>
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-700 mb-4">Email</h3>
              <p className="text-gray-600">info@example.com</p>
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-700 mb-4">Location</h3>
              <p className="text-gray-600">123 Main St, Anytown, USA</p>
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-700 mb-4">Booking Platform</h3>
              <a href="https://karitickets.com" target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:text-blue-700">
                karitickets.com
              </a>
            </div>
          </div>
        </motion.div>
      </div>

      {/* Decorative elements */}
      <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-background to-transparent z-10"></div>
    </section>
  )
}
